infile = open(ARGV[0])
linesub = []

infile.each{|line|
	linesub = line.chomp.split(" ")

	temp_A1 = []
	temp_A1 = linesub[-2].match(/..\((\d+,\d+)\),..\((\d+,\d+)\)/)
	
	if temp_A1 == nil
		infile.gets
		infile.gets
		infile.gets
		next
	end
	
	flag  = 0
	flag += 1 if temp_A1[1].split(",")[0] == "0"
	flag += 1 if temp_A1[2].split(",")[0] == "0"
	
	if flag == 2
		print line
		print infile.gets
		print infile.gets
		print infile.gets
	end
	if flag != 2
		infile.gets
		infile.gets
		infile.gets
	end	
}
